import com.mojang.serialization.Codec;
import it.unimi.dsi.fastutil.objects.ObjectArrayList;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.storage.loot.LootContext;
import net.minecraftforge.common.loot.IGlobalLootModifier;

public class AddMystDrop implements IGlobalLootModifier {
    public static final Codec<AddMystDrop> CODEC = Codec.unit(new AddMystDrop());

    @Override
    public ObjectArrayList<ItemStack> apply(ObjectArrayList<ItemStack> generatedLoot,
                                            LootContext context) {
        if (ModItems.MYST_INGOT.get() == null) return generatedLoot;
        if (context.getRandom().nextFloat() < 0.1f) {
            generatedLoot.add(new ItemStack(ModItems.MYST_INGOT.get()));
        }
        return generatedLoot;
    }
}

