package com.example.examplemod.network;

import net.minecraft.resources.ResourceLocation;
import net.minecraftforge.network.NetworkRegistry;
import net.minecraftforge.network.simple.SimpleChannel;

import java.util.function.Supplier;

public class Networking1 {
    private static final String VERSION = "1";
    public static final SimpleChannel CHANNEL = NetworkRegistry.newSimpleChannel(
            new ResourceLocation("examplemod", "main"),
            () -> VERSION, VERSION::equals, VERSION::equals);

    public static void register() {
        int id = 0;
        CHANNEL.registerMessage(id++, PingMessage.class,
                PingMessage::encode, PingMessage::decode, PingMessage::handle);
    }

    public record PingMessage(long time) {
        public static void encode(PingMessage msg, net.minecraft.network.FriendlyByteBuf buf) {
            buf.writeLong(msg.time());
        }

        public static PingMessage decode(net.minecraft.network.FriendlyByteBuf buf) {
            return new PingMessage(buf.readLong());
        }

        public static void handle(PingMessage msg, Supplier<net.minecraftforge.network.NetworkEvent.Context> ctx) {
            ctx.get().setPacketHandled(true);
        }
    }
}

