package com.example.examplemod.network;

public class PacketRateGuard {
    private static long lastSendMs;

    // client-side throttle: never spam the server
    public static synchronized boolean canSend(long now, long cooldown) {
        if (now - lastSendMs < cooldown) return false;
        lastSendMs = now;
        return true;
    }
}

