package com.example.examplemod;

import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

public class AttachmentLikeData {
    // 1.20.1 has no attachment API: map keyed by entity UUID.
    // forgetting clearOnLogout leaks one entry per session
    private static final Map<UUID, Integer> CHARGES = new ConcurrentHashMap<>();

    public static int get(UUID id) {
        return CHARGES.getOrDefault(id, 0);
    }

    public static void set(UUID id, int v) {
        CHARGES.put(id, Math.max(0, v));
    }

    public static void clearOnLogout(UUID id) {
        CHARGES.remove(id);
    }
}

